import {buildLesson,lessons} from './lesson-core.js';
import {srt} from './core.js';
import {wrapCaption} from './coach-core.js';
const $=id=>document.getElementById(id);let data={shots:[],samples:[]},cancelled=false,videoURL=null,subtitleURL=null,teaching=false;
export function updateTeaching(shots,samples){if(!shots.length){$('teach-result').hidden=true;$('teach-video').pause()}data={shots:structuredClone(shots),samples};const select=$('teach-shot'),old=select.value;select.replaceChildren();const all=document.createElement('option');all.value='all';all.textContent=`全部 ${shots.length} 个镜头`;select.append(all);shots.forEach((shot,i)=>{const op=document.createElement('option');op.value=i;op.textContent=`镜头 ${i+1} · ${shot.start.toFixed(1)}–${shot.end.toFixed(1)} 秒`;select.append(op)});select.value=[...select.options].some(o=>o.value===old)?old:'all';$('teach-status').textContent=shots.length?'可生成全部或单个镜头的教学；每步按文字长度留出阅读时间。无配音，动画是操作示意。':'先完成拉片抽帧。'}
export function tutorialCard(shot){const recipe=lessons[shot.effect]||lessons['硬切 / 节奏切换'];const box=document.createElement('details');box.className='shot-lesson';const title=document.createElement('summary');title.textContent='在剪映中怎么做';box.append(title);const list=document.createElement('ol');for(const text of recipe.steps){const li=document.createElement('li');li.textContent=text;list.append(li)}box.append(list);const p=document.createElement('p');p.textContent=recipe.parameter+'。'+recipe.check;box.append(p);return box}
$('teach-cancel').onclick=()=>{cancelled=true};
function text(ctx,value,x,y,width,size=19,color='#292a2d',maxLines=5){ctx.font=`${size}px sans-serif`;ctx.fillStyle=color;const lines=wrapCaption(value,width,s=>ctx.measureText(s).width);lines.slice(0,maxLines).forEach((line,i)=>ctx.fillText(line,x,y+i*size*1.55));}
function fit(ctx,image,x,y,width,height,scale=1){const f=Math.min(width/image.width,height/image.height)*scale;ctx.save();ctx.beginPath();ctx.rect(x,y,width,height);ctx.clip();ctx.drawImage(image,x+(width-image.width*f)/2,y+(height-image.height*f)/2,image.width*f,image.height*f);ctx.restore()}
function draw(ctx,segment,image,t,position,total){const w=960,h=540;ctx.fillStyle='#faf7f0';ctx.fillRect(0,0,w,h);text(ctx,'CLIPPILOT / 剪映复现教学',34,39,900,16,'#706b63');text(ctx,`镜头 ${segment.shot} · ${segment.range} · ${segment.effect}`,34,78,900,25,'#142fb8',1);text(ctx,'参考帧 + 效果动画示意',34,117,420,14,'#6d685f');ctx.fillStyle='#23202c';ctx.fillRect(34,135,420,240);
 const p=Math.max(0,Math.min(1,t/segment.duration)),effect=segment.effect;ctx.save();if(effect==='叠化 / 淡入淡出')ctx.globalAlpha=Math.min(1,p*4,(1-p)*4);fit(ctx,image,34,135,420,240,effect==='缓慢推近'?1+.08*p:1);ctx.restore();
 if(effect==='重点字幕'){ctx.fillStyle='#000b';ctx.fillRect(62,310,362,43);text(ctx,'重点词  ·  对齐实际口播',80,338,340,21,'#ffdf65',1)}
 if(effect==='画中画 / 细节叠加'){ctx.fillStyle='#fff';ctx.fillRect(303,272,142,94);fit(ctx,image,308,277,132,84,1.3)}
 if(effect==='硬切 / 节奏切换'){ctx.fillStyle='#093fff';ctx.fillRect(34+420*p,371,3,4)}
 if(effect==='快慢变速'){ctx.strokeStyle='#093fff';ctx.lineWidth=3;ctx.beginPath();[[50,404],[135,380],[240,421],[350,404],[430,404]].forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();ctx.fillStyle='#093fff';ctx.beginPath();ctx.arc(50+380*p,402,6,0,Math.PI*2);ctx.fill();}
 text(ctx,`步骤 ${segment.step+1} / 3`,490,143,430,18,'#093fff',1);text(ctx,segment.text,490,185,420,23,'#292a2d',6);text(ctx,segment.parameter,34,446,890,17,'#555148',2);text(ctx,'操作示意，非剪映录屏；参数为试做起点，不能证明原片使用同一效果。',34,497,900,14,'#81796d',1);ctx.fillStyle='#093fff';ctx.fillRect(0,534,w*position/total,6);}
$('teach-export').onclick=async()=>{
 if(teaching)return;teaching=true;let rec,stream,timer,states;try{
  const segments=buildLesson(data.shots,data.samples,$('teach-shot').value);if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)throw Error('请使用支持 WebM 导出的桌面 Chrome');
  const images=new Map();for(const segment of segments)if(!images.has(segment.image)){const image=new Image();image.src=segment.image;await image.decode();images.set(segment.image,image)}
  document.dispatchEvent(new Event('stop-preview'));states=new Map([...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]));states.forEach((_,e)=>e.disabled=true);document.querySelectorAll('video').forEach(v=>v.pause());$('teach-cancel').hidden=false;$('teach-cancel').disabled=false;cancelled=false;
  const canvas=$('teach-canvas');canvas.hidden=false;const ctx=canvas.getContext('2d'),duration=segments.at(-1).start+segments.at(-1).duration;draw(ctx,segments[0],images.get(segments[0].image),0,0,duration);
  stream=canvas.captureStream(30);const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)throw Error('此浏览器不支持 WebM 编码');rec=new MediaRecorder(stream,{mimeType:mime});const chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  await new Promise((resolve,reject)=>{let failure=null;const finish=()=>{clearInterval(timer);if(rec.state!=='inactive')rec.stop()};rec.onstop=()=>failure?reject(failure):resolve();rec.onerror=()=>{failure=Error('教学视频编码失败');finish()};const start=performance.now();rec.start(1000);timer=setInterval(()=>{try{if(cancelled)throw Error('已取消，未生成新文件');if(document.hidden)throw Error('页面已进入后台，已停止导出；保持页面前台后重试');const elapsed=Math.min(duration,(performance.now()-start)/1000),segment=segments.find(s=>elapsed>=s.start&&elapsed<s.start+s.duration)||segments.at(-1);draw(ctx,segment,images.get(segment.image),elapsed-segment.start,elapsed,duration);$('teach-status').textContent=`正在生成教学视频：${elapsed.toFixed(1)} / ${duration} 秒，请保持前台…`;if(elapsed>=duration)finish()}catch(e){failure=e;finish()}},1000/30)});
  const blob=new Blob(chunks,{type:mime});if(!blob.size)throw Error('生成文件为空');if(videoURL)URL.revokeObjectURL(videoURL);if(subtitleURL)URL.revokeObjectURL(subtitleURL);videoURL=URL.createObjectURL(blob);subtitleURL=URL.createObjectURL(new Blob([srt({clips:segments.map(s=>({start:0,end:s.duration,caption:s.text}))})],{type:'text/plain;charset=utf-8'}));$('teach-video').src=videoURL;$('teach-download').href=videoURL;$('teach-srt').href=subtitleURL;$('teach-result').hidden=false;const a=document.createElement('a');a.href=videoURL;a.download='ClipPilot-剪映教学.webm';a.click();$('teach-status').textContent=`教学视频已生成，${duration} 秒。请播放核对，可另存字幕；没有配音或原音轨。`;
 }catch(e){$('teach-status').textContent='教学导出：'+e.message}finally{teaching=false;clearInterval(timer);if(rec&&rec.state!=='inactive')rec.stop();stream?.getTracks().forEach(t=>t.stop());$('teach-canvas').hidden=true;$('teach-cancel').hidden=true;states?.forEach((disabled,e)=>e.disabled=disabled)}
};
